import{I as s,o as p,c as d,j as e,a as i,J as n,w as r,b6 as c}from"./chunks/framework.BUXTSoD9.js";const m={style:{margin:"50px 0"}},f=JSON.parse(`{"title":"Trouver une bonne idée - Des besoins utilisateur à un produit qui se vend","description":"Apprenez à découvrir des opportunités commerciales dans les frustrations quotidiennes, maîtrisez la méthodologie systématique d'analyse des besoins, et transformez une idée ordinaire en un concept de produit que les utilisateurs sont prêts à payer.","frontmatter":{"title":"Trouver une bonne idée - Des besoins utilisateur à un produit qui se vend","description":"Apprenez à découvrir des opportunités commerciales dans les frustrations quotidiennes, maîtrisez la méthodologie systématique d'analyse des besoins, et transformez une idée ordinaire en un concept de produit que les utilisateurs sont prêts à payer."},"headers":[],"relativePath":"fr-fr/stage-1/finding-great-idea/index.md","filePath":"fr-fr/stage-1/finding-great-idea/index.md"}`),g={name:"fr-fr/stage-1/finding-great-idea/index.md"},q=Object.assign(g,{setup(v){const a="environ <strong>3 heures</strong>";return(h,t)=>{const o=s("ChapterIntroduction"),l=s("StepBar"),u=s("ClientOnly");return p(),d("div",null,[t[1]||(t[1]=e("h1",{id:"module-2-trouver-une-bonne-idee",tabindex:"-1"},[i("Module 2 : Trouver une bonne idée "),e("a",{class:"header-anchor",href:"#module-2-trouver-une-bonne-idee","aria-label":"Permalink to “Module 2 : Trouver une bonne idée”"},"​")],-1)),t[2]||(t[2]=e("h2",{id:"introduction-au-chapitre",tabindex:"-1"},[i("Introduction au chapitre "),e("a",{class:"header-anchor",href:"#introduction-au-chapitre","aria-label":"Permalink to “Introduction au chapitre”"},"​")],-1)),n(o,{duration:a,tags:["Découverte des besoins","Pensée produit","Analyse utilisateur","Modèle économique"],coreOutput:"3 concepts de produit validés",expectedOutput:"Direction entrepreneuriale / produit actionnable"},{default:r(()=>[...t[0]||(t[0]=[e("p",null,[i("Dans le chapitre précédent, nous avons appris à utiliser un AI IDE pour créer des choses, mais il y a une question plus fondamentale : "),e("strong",null,"que créer ?")],-1),e("p",null,[i(`Beaucoup de gens veulent d'emblée "faire un outil IA" ou "créer une plateforme sociale", mais le résultat final n'intéresse personne. Le problème ? `),e("strong",null,"Ils n'ont pas trouvé un vrai besoin.")],-1),e("p",null,[i("La réalité est encore plus cruelle : "),e("strong",null,"beaucoup de produits résolvent un problème, mais les utilisateurs refusent tout simplement de payer.")],-1),e("p",null,"Dans ce chapitre, nous allons suivre l'histoire de Xiaoming pour apprendre à trouver une direction produit qui vaut la peine d'être poursuivie.",-1),e("p",null,[i("À la fin de ce chapitre, vous disposerez d'une "),e("strong",null,"méthodologie complète pour trouver des idées"),i(", ainsi que de 3 concepts de produit validés.")],-1)])]),_:1}),e("div",m,[n(u,null,{default:r(()=>[n(l,{active:0,items:[{title:"Step 1",description:"Établir des critères de jugement"},{title:"Step 2",description:"Explorer les frustrations quotidiennes"},{title:"Step 3",description:"Segmenter les groupes d'utilisateurs"},{title:"Step 4",description:"Approfondir les scénarios"},{title:"Step 5",description:"Valider l'authenticité du besoin"},{title:"Step 6",description:"Affiner le concept de produit"}]})]),_:1})]),t[3]||(t[3]=c(`<h2 id="step-1-etablir-des-criteres-de-jugement-quels-besoins-les-utilisateurs-sont-ils-prets-a-payer" tabindex="-1">Step 1 : Établir des critères de jugement -- Quels besoins les utilisateurs sont-ils prêts à payer ? <a class="header-anchor" href="#step-1-etablir-des-criteres-de-jugement-quels-besoins-les-utilisateurs-sont-ils-prets-a-payer" aria-label="Permalink to “Step 1 : Établir des critères de jugement -- Quels besoins les utilisateurs sont-ils prêts à payer ?”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Pourquoi ce chapitre est-il important ?</p><p>Certains pourraient trouver cela étrange : &quot;Ce n&#39;est pas un cours de Vibe Coding ? Pourquoi apprendre d&#39;abord à &#39;trouver des besoins&#39; ? Ne peut-on pas simplement commencer à coder ?&quot;</p><p>En effet, la plupart des cours de programmation vous enseignent directement à réaliser des projets : faire un Todo List, une calculatrice, un blog personnel... Ces projets vous aident certes à vous familiariser avec la syntaxe et les outils, mais le problème est :</p><p><strong>Si la direction est mauvaise, plus vous avancez, plus vous vous égarez.</strong></p><p>Imaginez :</p><ul><li>Vous passez deux semaines à créer un &quot;système de gestion de calendrier&quot;, mais il en existe déjà 100 meilleurs sur le marché</li><li>Vous créez un &quot;calculateur de calories par photo&quot;, mais les utilisateurs le désinstallent après une seule utilisation</li><li>Vous faites un &quot;carnet de dépenses personnel&quot;, mais vous-mêmes êtes trop paresseux pour l&#39;utiliser</li></ul><p>Ces projets terminés, pouvez-vous les mettre sur votre CV ? Probablement pas, car <strong>ils ne résolvent pas de problèmes réels et ne créent pas de valeur réelle</strong>.</p><p>Puisque nous allons investir du temps dans l&#39;apprentissage, pourquoi ne pas viser de meilleurs résultats ?</p><p>Puisque le Vibe Coding nous permet de transformer rapidement une idée en produit, nous devrions d&#39;autant plus apprendre à <strong>trouver des idées qui valent la peine d&#39;être réalisées</strong>. En nous entraînant de la manière la plus proche de la réalité -- non pas en faisant des &quot;projets d&#39;exercice&quot;, mais en créant des &quot;produits que les gens veulent utiliser&quot;.</p><p>C&#39;est pourquoi nous devons d&#39;abord apprendre à &quot;trouver une bonne idée&quot;.</p><hr><p><strong>L&#39;auteur estime personnellement</strong> que le temps est précieux, <strong>puisque nous faisons les choses, faisons-les du mieux possible</strong>, sinon pourquoi ne pas simplement jouer ? En tant que responsable, l&#39;auteur s&#39;efforcera aussi de vous soutenir pour que vous donniez le meilleur de vous-même.</p><p>Même si personne d&#39;autre ne croit en vous, l&#39;auteur espérera fermement que vous pourrez donner le meilleur de vous-même. Ayant choisi le vibecoding pour créer des produits, voyez jusqu&#39;où vous pouvez aller !</p></div><hr><h2 id="ouverture-l-histoire-de-xiaoming-developpeur-independant" tabindex="-1">Ouverture : L&#39;histoire de Xiaoming, développeur indépendant <a class="header-anchor" href="#ouverture-l-histoire-de-xiaoming-developpeur-independant" aria-label="Permalink to “Ouverture : L&#39;histoire de Xiaoming, développeur indépendant”">​</a></h2><p>Xiaoming est programmeur et travaille depuis trois ans. Un jour, il a eu une idée : et si je créais une application de fitness pour aider les utilisateurs à planifier leurs entraînements et suivre leurs données d&#39;exercice ? Cette idée l&#39;a enthousiasmé, il se sentait enfin prêt à se lancer.</p><p>L&#39;année suivante, Xiaoming a consacré presque tout son temps libre au projet. Il a créé une application très complète -- module de cours, système de suivi, fonctionnalité communautaire, analyse de données, tout ce qu&#39;il fallait. L&#39;interface était plutôt réussie, du moins il en était satisfait.</p><p>Le jour du lancement, Xiaoming était plein d&#39;espoir. Il a investi pas mal d&#39;argent en marketing, et dès le premier mois, 50 000 personnes ont téléchargé l&#39;application. Pas mal comme début, non ?</p><p>Mais très vite, les problèmes sont apparus. Les utilisateurs téléchargeaient l&#39;application, l&#39;utilisaient une fois, puis la désinstallaient. Le taux de rétention à 7 jours n&#39;était que de 5 %. Il a mis en place plusieurs fonctionnalités payantes, mais presque aucun utilisateur n&#39;était prêt à payer. Plus décourageant encore, des produits établis comme Keep, Boohee et FitTime offraient plus de fonctionnalités et un meilleur contenu. Pourquoi les utilisateurs passeraient-ils à son application ?</p><p>Au bout d&#39;un an, Xiaoming avait perdu 200 000 yuan.</p><p>Assis devant son ordinateur, regardant les données décevantes du tableau de bord, il n&#39;avait qu&#39;une seule question : mon application est plutôt bien faite, pourquoi personne ne l&#39;utilise ? Et encore moins paie pour l&#39;utiliser ?</p><p>L&#39;échec de Xiaoming n&#39;est pas dû à un manque de compétences techniques, ni à un produit mal fait. Pour être honnête, son application avait beaucoup de fonctionnalités et une belle interface.</p><p><strong>Le problème vient du point de départ.</strong></p><p>Il ne s&#39;est jamais posé la question la plus fondamentale : les utilisateurs en ont-ils vraiment besoin ?</p><p>Il a vu que le marché des applications de fitness était énorme, que Keep était évalué à des milliards, et il a pensé que c&#39;était une bonne opportunité. Mais il n&#39;a pas clarifié plusieurs choses : pourquoi les utilisateurs auraient-ils besoin d&#39;une autre application de fitness ? Quelle est ma différenciation par rapport à Keep ? Les utilisateurs seraient-ils prêts à payer pour cela ?</p><p><strong>Si la direction est mauvaise, plus vous avancez, plus vous vous égarez.</strong> Il a passé un an à perfectionner une mauvaise direction, pour s&#39;éloigner de plus en plus du succès.</p><div class="tip custom-block"><p class="custom-block-title">Ce que nous allons faire dans ce chapitre</p><p>Dans ce chapitre, nous allons aider Xiaoming à analyser ce qui n&#39;a pas fonctionné, puis ensemble trouver une direction produit que les gens seraient réellement prêts à payer.</p><p>Nous procéderons en trois étapes :</p><p><strong>Première partie : Trouver le vrai besoin</strong> -- Comprendre d&#39;abord quels types de besoins les utilisateurs sont prêts à payer</p><p><strong>Deuxième partie : Extraire une bonne idée</strong> -- Apprendre à identifier des opportunités commerciales à partir d&#39;idées ordinaires</p><p><strong>Troisième partie : Affinage par conversation avec l&#39;IA</strong> -- Utiliser l&#39;IA pour transformer une idée en un plan de produit réalisable</p></div><hr><h2 id="premiere-partie-trouver-le-vrai-besoin" tabindex="-1">Première partie : Trouver le vrai besoin <a class="header-anchor" href="#premiere-partie-trouver-le-vrai-besoin" aria-label="Permalink to “Première partie : Trouver le vrai besoin”">​</a></h2><p>Xiaoming était découragé, mais n&#39;a pas abandonné. Il a commencé à réfléchir à une question : quels types de besoins les utilisateurs sont-ils réellement prêts à payer ?</p><h3 id="la-perplexite-de-xiaoming-pourquoi-les-utilisateurs-ne-paient-ils-pas" tabindex="-1">La perplexité de Xiaoming : pourquoi les utilisateurs ne paient-ils pas ? <a class="header-anchor" href="#la-perplexite-de-xiaoming-pourquoi-les-utilisateurs-ne-paient-ils-pas" aria-label="Permalink to “La perplexité de Xiaoming : pourquoi les utilisateurs ne paient-ils pas ?”">​</a></h3><p>Il est allé voir quelques amis qui avaient utilisé son application pour recueillir leurs avis sincères.</p><p>L&#39;ami A a dit : &quot;Ton application est plutôt bien, mais j&#39;utilise déjà Keep, pourquoi devrais-je changer ?&quot;</p><p>L&#39;ami B a dit : &quot;Tu me demandes d&#39;enregistrer chaque entraînement, c&#39;est trop compliqué, j&#39;ai la flemme.&quot;</p><p>L&#39;ami C a été plus direct : &quot;Les fonctionnalités gratuites suffisent, pourquoi devrais-je payer ?&quot;</p><p>Ces réponses ont fait réaliser à Xiaoming où se trouvait le problème.</p><p><strong>Premier problème : les utilisateurs ne changent pas parce que la solution actuelle est déjà suffisante.</strong> Des produits établis comme Keep ont déjà beaucoup de fonctionnalités, les habitudes sont prises, et le coût de migration est élevé. Pourquoi changeraient-ils pour un produit similaire ?</p><p><strong>Deuxième problème : les utilisateurs ne veulent pas changer leurs habitudes.</strong> Enregistrer chaque entraînement est trop fastidieux. Si un produit exige que les utilisateurs changent plus de 3 habitudes, il échouera probablement.</p><p><strong>Troisième problème : il y a trop d&#39;alternatives gratuites.</strong> Vos fonctionnalités sont trop génériques, sans valeur unique, et les utilisateurs ne trouvent aucune raison de payer.</p><h3 id="qu-est-ce-qu-un-vrai-besoin" tabindex="-1">Qu&#39;est-ce qu&#39;un vrai besoin ? <a class="header-anchor" href="#qu-est-ce-qu-un-vrai-besoin" aria-label="Permalink to “Qu&#39;est-ce qu&#39;un vrai besoin ?”">​</a></h3><p>Xiaoming a commencé à étudier les produits réussis pour lesquels les utilisateurs paient. Il a découvert un point commun : ces produits ne résolvent pas des besoins du type &quot;je trouve ça utile&quot;, mais des besoins pour lesquels les utilisateurs sont prêts à payer, à changer de comportement et à tolérer des désagréments.</p><p>Autrement dit, <strong>un vrai besoin est validé par les actes des utilisateurs, pas inventé par un chef de produit.</strong></p><h3 id="cas-les-produits-pour-lesquels-les-utilisateurs-paient" tabindex="-1">Cas : Les produits pour lesquels les utilisateurs paient <a class="header-anchor" href="#cas-les-produits-pour-lesquels-les-utilisateurs-paient" aria-label="Permalink to “Cas : Les produits pour lesquels les utilisateurs paient”">​</a></h3><p>Xiaoming a étudié plusieurs cas de réussite pour comprendre quels points de douleur ils avaient ciblés.</p><h4 id="meicai-permettre-aux-petits-restaurateurs-de-bien-dormir" tabindex="-1">Meicai : Permettre aux petits restaurateurs de bien dormir <a class="header-anchor" href="#meicai-permettre-aux-petits-restaurateurs-de-bien-dormir" aria-label="Permalink to “Meicai : Permettre aux petits restaurateurs de bien dormir”">​</a></h4><p>En surface, ce que fait Meicai est simple : aider les restaurants à acheter des légumes. Mais si vous y réfléchissez bien, pourquoi les restaurateurs l&#39;utiliseraient-ils ?</p><p>Parce que les petits restaurateurs doivent se lever à 4 heures du matin pour aller au marché de gros, c&#39;est épuisant, et ils se font souvent arnaquer. Ce que fait Meicai, ce n&#39;est pas simplement du &quot;e-commerce de légumes&quot;, c&#39;est restructurer toute la chaîne d&#39;approvisionnement pour que les petits restaurateurs puissent dormir tranquilles.</p><p>Plus le point de douleur est intense, plus la volonté de payer est forte. Le temps et l&#39;énergie économisés valent plus que les économies sur les légumes.</p><h4 id="xiaohongshu-resoudre-la-difficulte-de-choisir" tabindex="-1">Xiaohongshu : Résoudre la difficulté de choisir <a class="header-anchor" href="#xiaohongshu-resoudre-la-difficulte-de-choisir" aria-label="Permalink to “Xiaohongshu : Résoudre la difficulté de choisir”">​</a></h4><p>En surface, Xiaohongshu est un &quot;partage d&#39;expériences d&#39;achats à l&#39;étranger&quot;. Mais pourquoi les utilisateurs passent-ils du temps à lire des publications ?</p><p>Face à une quantité massive de produits, les utilisateurs ne savent pas ce qui vaut la peine d&#39;être acheté et ce qui ne l&#39;est pas. Ils ont besoin de quelqu&#39;un de confiance pour les aider à filtrer, gagner du temps et éviter les mauvais choix.</p><p>Xiaohongshu résout en réalité deux points de douleur profonds : la difficulté de choisir et le manque de confiance. Les utilisateurs sont prêts à payer pour &quot;gagner du temps&quot; et &quot;éviter les erreurs&quot;, c&#39;est pourquoi Xiaohongshu a réussi.</p><hr><p>Après avoir étudié ces cas, Xiaoming a fait une découverte importante.</p><p>Ce pour quoi les utilisateurs paient n&#39;est jamais une &quot;fonctionnalité&quot;, mais &quot;résoudre une peur&quot; et &quot;éliminer une anxiété&quot;. Meicai résout la peur des petits restaurateurs face à la difficulté des achats matinaux, Xiaohongshu résout la peur des utilisateurs de faire de mauvais achats.</p><p><strong>La peur motive le paiement, l&#39;anxiété motive l&#39;action.</strong></p><h3 id="les-trois-couches-des-besoins-point-de-douleur-point-de-satisfaction-point-de-demangeaison" tabindex="-1">Les trois couches des besoins : point de douleur, point de satisfaction, point de démangeaison <a class="header-anchor" href="#les-trois-couches-des-besoins-point-de-douleur-point-de-satisfaction-point-de-demangeaison" aria-label="Permalink to “Les trois couches des besoins : point de douleur, point de satisfaction, point de démangeaison”">​</a></h3><p>Xiaoming a approfondi ses recherches et a découvert que les besoins des utilisateurs peuvent être classés en trois types :</p><div class="tip custom-block"><p class="custom-block-title">Point de douleur (Pain Point) -- piloté par la peur</p><p><strong>Nature :</strong> Un problème que l&#39;utilisateur vit actuellement, qui le fait souffrir, s&#39;inquiéter ou le met en difficulté. Ne pas le résoudre est insupportable, voire menace sa survie ou sa sécurité.</p><p><strong>Exemples :</strong></p><ul><li>Les diabétiques ne savent pas combien de glucides provoqueront un pic de glycémie (peur : menace pour la santé)</li><li>Les petits restaurateurs se lèvent à 4 heures du matin pour aller au marché de gros (peur : difficulté de survie)</li></ul><p><strong>Clé :</strong> Les utilisateurs sont prêts à payer, car ne pas résoudre le problème est &quot;très douloureux&quot;.</p></div><div class="tip custom-block"><p class="custom-block-title">Point de satisfaction (Delight Point) -- gratification immédiate</p><p><strong>Nature :</strong> L&#39;utilisateur a un besoin qui peut être satisfait immédiatement, produisant une sensation de plaisir instantanée.</p><p><strong>Exemples :</strong></p><ul><li>Livraison de repas en 30 minutes (satisfaction immédiate de la faim)</li><li>Génération automatique de présentations élégantes (plaisir de gagner du temps et des efforts)</li></ul><p><strong>Clé :</strong> Rendre l&#39;utilisateur &quot;heureux&quot; est la clé de la fidélisation, mais comme point de paiement unique, c&#39;est faible.</p></div><div class="tip custom-block"><p class="custom-block-title">Point de démangeaison (Itch Point) -- moi virtuel</p><p><strong>Nature :</strong> L&#39;utilisateur veut devenir meilleur, plus cool, plus raffiné, mais ce n&#39;est pas indispensable. C&#39;est agréable si c&#39;est satisfait, et ce n&#39;est pas grave si ce ne l&#39;est pas.</p><p><strong>Exemples :</strong></p><ul><li>Enregistrer la quantité d&#39;eau bue chaque jour (image d&#39;une vie disciplinée)</li><li>Ajouter des filtres artistiques aux photos avec l&#39;IA (image d&#39;un goût artistique)</li></ul><p><strong>Clé :</strong> La volonté de payer pour un &quot;point de démangeaison&quot; est faible, car ne pas le résoudre n&#39;a pas de conséquences.</p></div><p>Quelle est la bonne priorité ? Une bonne recommandation est : point de douleur &gt; point de satisfaction &gt; point de démangeaison</p><p>Pourquoi ?</p><ol><li><strong>Le point de douleur est un besoin de survie :</strong> Ne pas le résoudre est insupportable (ou très douloureux), les utilisateurs doivent payer. C&#39;est un &quot;analgésique&quot;.</li><li><strong>Le point de satisfaction est une récompense immédiate :</strong> Rendez l&#39;utilisateur heureux, et il reviendra. C&#39;est une &quot;mécanisme d&#39;addiction&quot; (au sens positif).</li><li><strong>Le point de démangeaison est la satisfaction d&#39;un désir :</strong> C&#39;est optionnel, c&#39;est ce qui est le plus facilement éliminé. C&#39;est une &quot;vitamine&quot; ou un &quot;produit de luxe&quot;.</li></ol><p><strong>Insight clé :</strong> L&#39;erreur que font beaucoup de chefs de produit est de vendre un produit de type &quot;point de démangeaison&quot; avec des arguments de type &quot;point de douleur&quot;.</p><p>Par exemple : &quot;Enregistrer votre consommation d&#39;eau vous rendra plus en bonne santé&quot; -- boire de l&#39;eau est effectivement sain, mais ne pas l&#39;enregistrer ne vous rendra pas malade. C&#39;est emballer un point de démangeaison comme un point de douleur, les utilisateurs ne seront pas convaincus.</p><h3 id="la-methode-en-5-etapes-pour-valider-un-vrai-besoin" tabindex="-1">La méthode en 5 étapes pour valider un vrai besoin <a class="header-anchor" href="#la-methode-en-5-etapes-pour-valider-un-vrai-besoin" aria-label="Permalink to “La méthode en 5 étapes pour valider un vrai besoin”">​</a></h3><p>Xiaoming s&#39;est demandé : <strong>quand j&#39;ai une idée, comment puis-je rapidement déterminer si elle vaut la peine d&#39;investir ?</strong></p><p>Il a étudié la méthode de jugement en 5 étapes couramment utilisée par les chefs de produit (détails en Annexe A) :</p><ol><li><p><strong>Première étape : Discuter directement avec de vrais utilisateurs pour comprendre ce qu&#39;ils font actuellement</strong></p><p>Trouvez 10 utilisateurs cibles. Demandez-leur : &quot;Comment résolvez-vous ce problème actuellement ?&quot; Si l&#39;utilisateur utilise déjà une méthode, le problème existe vraiment. Si l&#39;utilisateur dit qu&#39;il n&#39;a pas besoin de le résoudre, ce n&#39;est probablement pas un vrai besoin.</p></li><li><p><strong>Deuxième étape : Analyser les solutions de remplacement actuelles des utilisateurs et identifier votre avantage</strong></p><p>Les utilisateurs utilisent peut-être d&#39;autres produits, Excel, leur mémoire, ou tolèrent le problème. Vous devez comprendre les défauts de ces solutions. Votre produit doit être nettement meilleur pour que les utilisateurs soient prêts à changer.</p></li><li><p><strong>Troisième étape : Tester si les utilisateurs sont prêts à payer pour votre produit</strong></p><p>Faites une prévente ou demandez un acompte. Calculez le pourcentage d&#39;utilisateurs prêts à payer un acompte (plus tôt vous gagnez de l&#39;argent, plus le besoin est confirmé) :</p><ul><li>Plus de 10 % : le besoin est réel, cela vaut l&#39;investissement</li><li>5 % à 10 % : le besoin existe, mais doit être affiné</li><li>Moins de 5 % : le besoin n&#39;est probablement pas valide</li></ul></li><li><p><strong>Quatrième étape : Estimer la taille du marché et la rentabilité potentielle</strong></p><p>Calculez trois chiffres : nombre total d&#39;utilisateurs cibles × volonté de payer × prix moyen. Le produit donne la taille du marché. Si le marché est trop petit, cela ne vaut peut-être pas la peine.</p></li><li><p><strong>Cinquième étape : Réfléchir aux barrières à l&#39;entrée de votre produit pour empêcher la copie</strong></p><p>Considérez ces barrières : difficulté technique, effet de réseau, marque, avantage de coût. Elles vous aideront à rester compétitif à long terme.</p></li></ol><p><strong>Résumé de cette partie : Ce que Xiaoming a appris</strong></p><ol><li><p><strong>Les critères d&#39;un vrai besoin</strong></p><ul><li>Le critère le plus important est la volonté de payer des utilisateurs.</li><li>Les utilisateurs sont prêts à changer de comportement.</li><li>Sans solution, les utilisateurs subissent une perte importante.</li></ul></li><li><p><strong>Éviter les faux besoins</strong></p><ul><li>Un point de démangeaison n&#39;est pas un point de douleur, il ne peut pas être considéré comme un vrai besoin.</li><li>Le marché est trop petit pour soutenir un modèle économique.</li><li>La solution est plus complexe que le problème, les utilisateurs abandonneront.</li></ul></li><li><p><strong>Ordre de priorité</strong></p><ul><li>La vraie priorité est : point de douleur &gt; point de satisfaction &gt; point de démangeaison.</li></ul></li></ol><p><strong>Résultat de cette partie</strong></p><ul><li>Je comprends ce qu&#39;est un vrai besoin.</li><li>Je maîtrise la classification en trois couches des besoins : point de douleur, point de satisfaction, point de démangeaison.</li><li>J&#39;ai appris à utiliser la méthode en 5 étapes pour valider l&#39;authenticité d&#39;un besoin.</li></ul><hr><h2 id="deuxieme-partie-extraire-une-bonne-idee" tabindex="-1">Deuxième partie : Extraire une bonne idée <a class="header-anchor" href="#deuxieme-partie-extraire-une-bonne-idee" aria-label="Permalink to “Deuxième partie : Extraire une bonne idée”">​</a></h2><p>Xiaoming sait maintenant ce qu&#39;est un vrai besoin, mais il ne sait toujours pas par où commencer. Il ne peut pas inventer un besoin à partir de rien.</p><p>Il a décidé de commencer par ce qu&#39;il connaît le mieux -- les gens et les choses autour de lui.</p><h3 id="partir-de-soi-meme-la-soeur-de-xiaoming" tabindex="-1">Partir de soi-même : La soeur de Xiaoming <a class="header-anchor" href="#partir-de-soi-meme-la-soeur-de-xiaoming" aria-label="Permalink to “Partir de soi-même : La soeur de Xiaoming”">​</a></h3><p>Xiaoming a pensé à sa soeur. Elle venait d&#39;avoir un bébé et se plaignait toujours de ne pas avoir le temps de faire de l&#39;exercice, de ne pas réussir à perdre du ventre, et d&#39;être très anxieuse.</p><p>Un jour, il lui a demandé : &quot;Comment résous-tu le problème du fitness actuellement ?&quot;</p><p>Sa soeur a soupiré : &quot;Je fais du sport avec Keep, mais ces exercices ne conviennent pas à un corps post-partum, mon dos me fait encore plus mal après. Aller à la salle de sport ? Personne pour garder le bébé. Prendre un coach personnel ? 300 à 500 yuans par séance, trop cher. M&#39;entraîner seule ? J&#39;ai peur de me blesser.&quot;</p><p>Xiaoming a compris que c&#39;était peut-être le vrai besoin qu&#39;il cherchait.</p><p>Les problèmes de sa soeur étaient en réalité très concrets : du temps fragmenté, besoin de s&#39;occuper du bébé, pas de bloc de temps pour faire du sport ; des limitations physiques, diastasis des muscles abdominaux, relâchement du plancher pelvien, pas d&#39;exercice intense possible ; beaucoup d&#39;anxiété, corps transformé, peur d&#39;être rejetée par son mari, complexe social ; trop d&#39;informations contradictoires, elle ne sait pas quels exercices sont adaptés au post-partum ; et un sentiment de solitude, personne ne comprend sa situation, manque de soutien.</p><p>Ce sont tous de vrais points de douleur, pas des points de démangeaison du type &quot;c&#39;est bien si on a&quot;.</p><hr><h3 id="segmentation-horizontale-les-besoins-de-differents-groupes" tabindex="-1">Segmentation horizontale : Les besoins de différents groupes <a class="header-anchor" href="#segmentation-horizontale-les-besoins-de-differents-groupes" aria-label="Permalink to “Segmentation horizontale : Les besoins de différents groupes”">​</a></h3><p>Xiaoming a réalisé que l&#39;idée &quot;application de fitness&quot; était trop vague. Il voulait aider tout le monde à faire du sport, mais le problème est que tout le monde a des besoins différents.</p><p>Il a fait une segmentation horizontale, divisant &quot;les personnes qui veulent faire du sport&quot; en plusieurs catégories (méthode détaillée en Annexe B) :</p><p>Les pratiquants de musculation ont besoin de calculer précisément leur apport en protéines, la saisie manuelle est trop fastidieuse, leur volonté de payer est élevée, ils recherchent l&#39;efficacité. Les diabétiques doivent contrôler strictement les glucides, mais manger au restaurant rend difficile l&#39;estimation, c&#39;est un besoin essentiel, ils sont prêts à payer et le taux de réachat est élevé. Les mamans post-partum veulent retrouver leur silhouette mais n&#39;ont pas le temps de calculer, elles ont besoin d&#39;une solution simple, sont sensibles au temps et ont besoin d&#39;un service clé en main. Les habitués de la livraison mangent au restaurant tous les jours sans savoir combien de calories ils consomment, c&#39;est un scénario fréquent, mais la volonté de payer est moyenne. Les étudiants préparant des concours ont besoin d&#39;outils d&#39;apprentissage efficaces, mais ne savent pas lesquels utiliser, c&#39;est un besoin essentiel, mais le prix moyen est faible.</p><p>Xiaoming a choisi le groupe des &quot;mamans post-partum&quot;. Pourquoi ?</p><p>D&#39;abord, il est lui-même utilisateur -- sa soeur est une maman post-partum, il comprend naturellement les points de douleur de ce groupe. Ensuite, le point de douleur est intense -- l&#39;anxiété de la récupération post-partum est réelle, pas un point de démangeaison. Troisièmement, la volonté de payer est forte -- les mamans sont prêtes à dépenser pour retrouver leur silhouette. Quatrièmement, la concurrence est relativement faible -- il n&#39;y a pas de produit spécifiquement dédié aux mamans post-partum sur le marché.</p><div class="tip custom-block"><p class="custom-block-title">La logique de segmentation du chef de produit</p><p>Pourquoi la segmentation est-elle si importante ?</p><p>Parce qu&#39;il est difficile de gagner avec un outil généraliste. Les grandes plateformes ont déjà conquis le marché &quot;général&quot;, il est difficile de les surpasser en fonctionnalités. Les besoins des segments spécifiques sont plus intenses -- pour les mamans post-partum, le fitness est un besoin essentiel, pour les pratiquants ordinaires c&#39;est juste &quot;ça irait&quot;. Servir bien un petit groupe est plus facile pour construire une réputation que d&#39;essayer de plaire à tout le monde. Les points de douleur des segments sont plus spécifiques et les utilisateurs sont plus disposés à payer pour une solution.</p></div><hr><h3 id="approfondissement-vertical-le-scenario-utilisateur-complet" tabindex="-1">Approfondissement vertical : Le scénario utilisateur complet <a class="header-anchor" href="#approfondissement-vertical-le-scenario-utilisateur-complet" aria-label="Permalink to “Approfondissement vertical : Le scénario utilisateur complet”">​</a></h3><p>Après avoir identifié le groupe cible, Xiaoming ne s&#39;est pas arrêté à la fonctionnalité unique de &quot;fitness post-partum&quot;. Il a voulu mieux comprendre le scénario utilisateur complet (méthode détaillée en Annexe C).</p><p>Il a observé une journée dans la vie de sa soeur.</p><p>À 6 heures du matin, le bébé venait de s&#39;endormir, sa soeur avait 30 minutes de libre. Elle voulait faire de l&#39;exercice, mais craignait de réveiller le bébé et ne savait pas quels mouvements étaient sûrs.</p><p>À 10 heures, sa soeur berçait le bébé pour le faire dormir, le dos lui faisait mal. Elle voulait faire des exercices de rééducation, mais ses mains étaient occupées.</p><p>À 15 heures, le bébé dormait, sa soeur voulait faire du sport. Mais elle était très fatiguée et ne savait pas si elle pouvait encore s&#39;entraîner.</p><p>À 20 heures, sa soeur avait enfin du temps libre, mais elle était très anxieuse. Elle se regardait dans le miroir, se sentait détruite, et pleurait en regardant ses anciennes photos.</p><p>Xiaoming a découvert que le point de douleur de sa soeur n&#39;était pas &quot;l&#39;absence de cours de fitness&quot;, mais &quot;la peur et l&#39;anxiété de la récupération post-partum&quot;.</p><hr><div class="info custom-block"><p class="custom-block-title">La pensée par scénarios du chef de produit</p><p>Beaucoup pensent que les points de douleur sont des besoins fonctionnels, mais ce n&#39;est pas le cas. Un point de douleur est une émotion dans un scénario combinée à une volonté de payer.</p><p>Quand une maman post-partum fait face à son corps transformé dans le miroir, le vrai point de douleur n&#39;est pas &quot;je ne sais pas comment faire du sport&quot;, mais la peur -- crainte d&#39;une mauvaise récupération avec des séquelles ; l&#39;anxiété -- en se regardant dans le miroir, elle a l&#39;impression que sa vie est finie ; l&#39;impuissance -- ne pas savoir par où commencer, sans personne pour guider ; la solitude -- les autres reprennent vite, alors qu&#39;elle met du temps à se remettre.</p><p>Un bon design de produit résout des émotions, pas seulement des fonctionnalités. Derrière les émotions se trouve la motivation au paiement.</p></div><hr><h3 id="reconstruction-de-la-valeur-d-une-application-de-fitness-a-une-assistante-de-recuperation-post-partum" tabindex="-1">Reconstruction de la valeur : D&#39;une &quot;application de fitness&quot; à une &quot;assistante de récupération post-partum&quot; <a class="header-anchor" href="#reconstruction-de-la-valeur-d-une-application-de-fitness-a-une-assistante-de-recuperation-post-partum" aria-label="Permalink to “Reconstruction de la valeur : D&#39;une &quot;application de fitness&quot; à une &quot;assistante de récupération post-partum&quot;”">​</a></h3><p>Sur la base de cette analyse, Xiaoming a redessiné le produit.</p><div class="tip custom-block"><p class="custom-block-title">Concept de produit reconstruit : &quot;Assistante de récupération post-partum&quot;</p><p><strong>Positionnement central :</strong> Pas seulement un outil de fitness, mais une &quot;coach de rééducation personnelle + soutien psychologique&quot; pour les mamans post-partum</p><p><strong>Fonctionnalités clés :</strong></p><ol><li><p><strong>Entraînements fragmentés :</strong></p><ul><li>Seulement 10-15 minutes par session</li><li>Possibilité de s&#39;entraîner même quand le bébé dort</li><li>Exercices adaptés pour &quot;être faits en portant le bébé&quot;</li></ul></li><li><p><strong>Cours spécifiques post-partum :</strong></p><ul><li>Classés par stade post-partum (0-3 mois, 3-6 mois, plus de 6 mois)</li><li>Entraînements ciblés pour le diastasis abdominal et la rééducation du plancher pelvien</li><li>Chaque exercice inclut des &quot;précautions post-partum&quot;</li></ul></li><li><p><strong>Correction des mouvements par IA :</strong></p><ul><li>Reconnaissance des mouvements par la caméra du téléphone</li><li>Retours en temps réel : &quot;genoux trop fléchis&quot;, &quot;dos à redresser&quot;</li><li>Éviter les blessures dues à des mouvements incorrects</li></ul></li><li><p><strong>Communauté de soutien psychologique :</strong></p><ul><li>Communauté privée uniquement pour les mamans post-partum</li><li>Partage des progrès de récupération, encouragement mutuel</li><li>Intégration de conseillers psychologues professionnels</li></ul></li><li><p><strong>Plans personnalisés :</strong></p><ul><li>Personnalisés selon le mode d&#39;accouchement (naturel/césarienne) et la condition physique</li><li>Prise en compte des besoins spécifiques de l&#39;allaitement</li></ul></li></ol><p><strong>Modèle économique :</strong></p><ul><li>Cours de base gratuits</li><li>Cours avancés : 99 yuans/mois (avec correction IA et plan personnalisé)</li><li>Coaching individuel : 299 yuans/mois (guidance en ligne)</li><li>Adhésion communautaire : 199 yuans/an (avec soutien psychologique et réponses d&#39;experts)</li></ul><p><strong>Barrières concurrentielles :</strong></p><ul><li>Professionnalisme : partenariat avec des centres de rééducation post-partum, soutien médical</li><li>Adhésion communautaire : les connexions émotionnelles entre mamans post-partum sont fortes</li><li>Accumulation de données : plus il y a de données corporelles, plus les plans sont précis</li></ul><p><strong>Taille du marché :</strong></p><ul><li>Environ 10 millions de nouveau-nés par an en Chine</li><li>Marché de la rééducation post-partum : environ 50 milliards de yuans</li><li>Objectif : servir 1 % des mamans post-partum = 100 000 utilisateurs</li><li>ARPU (revenu moyen par utilisateur) : 500 yuans/an</li><li>Revenu potentiel : 50 millions de yuans/an</li></ul></div><p>Comparaison entre l&#39;idée originale et le concept reconstruit :</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Idée originale</th><th>Après reconstruction</th></tr></thead><tbody><tr><td>Utilisateurs cibles</td><td>Tous les sportifs (large et vague)</td><td>Mamans post-partum (précis)</td></tr><tr><td>Point de douleur résolu</td><td>Enregistrer les entraînements (point de démangeaison)</td><td>Anxiété de récupération post-partum (point de douleur)</td></tr><tr><td>Barrière concurrentielle</td><td>Technologie (facilement copiable)</td><td>Professionnalisme + communauté + données</td></tr><tr><td>Volonté de payer</td><td>Faible (beaucoup d&#39;alternatives gratuites)</td><td>Élevée (besoin essentiel + valeur émotionnelle)</td></tr><tr><td>Potentiel d&#39;extension</td><td>Limité</td><td>Extensible à la grossesse et à la préparation</td></tr></tbody></table><p><strong>C&#39;est l&#39;évolution d&#39;&quot;une fonctionnalité&quot; à &quot;un produit que les gens paient&quot;.</strong></p><hr><h3 id="plus-d-exemples-d-une-idee-ordinaire-a-une-bonne-idee" tabindex="-1">Plus d&#39;exemples : D&#39;une idée ordinaire à une bonne idée <a class="header-anchor" href="#plus-d-exemples-d-une-idee-ordinaire-a-une-bonne-idee" aria-label="Permalink to “Plus d&#39;exemples : D&#39;une idée ordinaire à une bonne idée”">​</a></h3><p>Xiaoming trouvait cette méthode très utile. Il a analysé d&#39;autres exemples avec la même approche pour vérifier qu&#39;elle était universelle (cas détaillés en Annexe D).</p><h4 id="exemple-1-de-calcul-de-calories-a-manger-serein-pour-diabetiques" tabindex="-1">Exemple 1 : De &quot;calcul de calories&quot; à &quot;Manger serein pour diabétiques&quot; <a class="header-anchor" href="#exemple-1-de-calcul-de-calories-a-manger-serein-pour-diabetiques" aria-label="Permalink to “Exemple 1 : De &quot;calcul de calories&quot; à &quot;Manger serein pour diabétiques&quot;”">​</a></h4><p>L&#39;idée ordinaire est de photographier les aliments pour identifier les calories, aider les personnes au régime à contrôler leur alimentation. Mais le problème est qu&#39;il existe déjà des produits établis comme Boohee et MyFitnessPal.</p><p>Xiaoming a fait une segmentation et a découvert que le groupe des diabétiques était intéressant : ils doivent contrôler strictement les glucides, mais manger au restaurant rend l&#39;estimation difficile. En approfondissant leurs scénarios : avant le repas, ils ne savent pas s&#39;ils peuvent manger tel plat, craignant un pic de glycémie ; pendant le repas, ils ont besoin d&#39;un rappel en temps réel &quot;vous avez déjà consommé tant de glucides&quot; ; après le repas, ils doivent enregistrer les variations de glycémie pour voir la relation avec l&#39;alimentation.</p><p>Le produit reconstruit s&#39;appelle &quot;Manger serein pour diabétiques&quot;, positionné comme &quot;assistant de sécurité alimentaire pour les diabétiques&quot;.</p><hr><h4 id="exemple-2-de-assistant-d-actualites-a-officier-de-renseignement-pour-analystes-financiers" tabindex="-1">Exemple 2 : De &quot;assistant d&#39;actualités&quot; à &quot;Officier de renseignement pour analystes financiers&quot; <a class="header-anchor" href="#exemple-2-de-assistant-d-actualites-a-officier-de-renseignement-pour-analystes-financiers" aria-label="Permalink to “Exemple 2 : De &quot;assistant d&#39;actualités&quot; à &quot;Officier de renseignement pour analystes financiers&quot;”">​</a></h4><p>L&#39;idée ordinaire est d&#39;agréger les actualités de différentes plateformes pour éviter d&#39;avoir à les ouvrir une par une. Mais des produits comme Jinri Toutiao et Tencent News le font déjà très bien.</p><p>Après segmentation, Xiaoming a découvert que les analystes financiers ont des besoins spécifiques : ils doivent suivre les tendances de secteurs particuliers, mais les informations sont trop dispersées. En approfondissant leurs scénarios : le matin, ils consultent les variations boursières américaines overnight et les taux de change ; l&#39;après-midi, ils suivent les annonces des entreprises de leur portefeuille et les nouvelles sectorielles ; ils ont besoin de grandes quantités d&#39;informations sectorielles pour analyser de potentiels investissements.</p><p>Le produit reconstruit s&#39;appelle &quot;Officier de renseignement pour analystes financiers&quot;, positionné comme &quot;radar d&#39;information et assistant décisionnel pour les professionnels de la finance&quot;.</p><hr><h4 id="exemple-3-de-plateforme-de-seconde-main-universitaire-a-assistant-de-vide-grenier-pour-diplomes" tabindex="-1">Exemple 3 : De &quot;plateforme de seconde main universitaire&quot; à &quot;Assistant de vide grenier pour diplômés&quot; <a class="header-anchor" href="#exemple-3-de-plateforme-de-seconde-main-universitaire-a-assistant-de-vide-grenier-pour-diplomes" aria-label="Permalink to “Exemple 3 : De &quot;plateforme de seconde main universitaire&quot; à &quot;Assistant de vide grenier pour diplômés&quot;”">​</a></h4><p>L&#39;idée ordinaire est une plateforme de transactions de seconde main sur les campus. Mais Xianyu et Zhuanzhuan le font déjà très bien.</p><p>Après segmentation, Xiaoming a découvert que les diplômés ont des besoins spécifiques : trop de choses, vendre une par une est trop fastidieux. En approfondissant leurs scénarios : il faut quitter le campus une semaine avant la fin des études, pas le temps de vendre lentement ; ils ne savent pas qui pourrait vouloir leurs affaires ; négocier, livrer, encaisser, c&#39;est trop compliqué.</p><p>Le produit reconstruit s&#39;appelle &quot;Assistant de vide grenier pour diplômés&quot;, positionné comme &quot;gestionnaire de patrimoine pour les départs&quot;.</p><hr><h3 id="resume-de-cette-partie-ce-que-xiaoming-a-appris" tabindex="-1">Résumé de cette partie : Ce que Xiaoming a appris <a class="header-anchor" href="#resume-de-cette-partie-ce-que-xiaoming-a-appris" aria-label="Permalink to “Résumé de cette partie : Ce que Xiaoming a appris”">​</a></h3><p>Grâce à cette deuxième partie, Xiaoming a compris :</p><p><strong>1. Partir de soi-même</strong></p><ul><li>Vous êtes vous-même utilisateur, vous comprenez naturellement les points de douleur de ce groupe</li><li>Les passions sont le meilleur point de départ, l&#39;enthousiasme est le meilleur moteur</li></ul><p><strong>2. Segmenter horizontalement les groupes</strong></p><ul><li>Ne pas servir &quot;tout le monde&quot;, trouver &quot;le groupe le plus touché&quot;</li><li>Plus le segment est étroit, plus il y a d&#39;opportunités, plus la volonté de payer est forte</li></ul><p><strong>3. Approfondir verticalement les scénarios</strong></p><ul><li>Décrire le parcours utilisateur complet : avant, pendant et après l&#39;utilisation</li><li>Trouver les déclencheurs émotionnels : peur, anxiété, impuissance, solitude...</li></ul><p><strong>4. Reconstruction de la valeur</strong></p><ul><li>Passer de &quot;fonctionnalité&quot; à &quot;solution&quot;</li><li>Passer d&#39;&quot;outil&quot; à &quot;assistant / gestionnaire / partenaire&quot;</li></ul><hr><p>📦 <strong>Résultat de cette partie :</strong></p><ul><li>Un groupe cible précis identifié (mamans post-partum)</li><li>Compréhension du scénario utilisateur complet et des émotions réelles</li><li>Concept de produit reconstruit avec un positionnement différencié clair</li></ul><hr><h2 id="troisieme-partie-affinage-par-conversation-avec-l-ia" tabindex="-1">Troisième partie : Affinage par conversation avec l&#39;IA <a class="header-anchor" href="#troisieme-partie-affinage-par-conversation-avec-l-ia" aria-label="Permalink to “Troisième partie : Affinage par conversation avec l&#39;IA”">​</a></h2><p>Xiaoming a maintenant une direction produit claire : une assistante de récupération post-partum. Mais il ne sait toujours pas comment procéder concrètement, par où commencer, et si la réalisation technique est difficile.</p><p>Il a décidé d&#39;utiliser l&#39;IA pour l&#39;aider à affiner son concept de produit et transformer son idée en plan exécutable.</p><h3 id="premier-tour-presenter-l-idee-originale" tabindex="-1">Premier tour : Présenter l&#39;idée originale <a class="header-anchor" href="#premier-tour-presenter-l-idee-originale" aria-label="Permalink to “Premier tour : Présenter l&#39;idée originale”">​</a></h3><p>Xiaoming a expliqué son idée à l&#39;IA : &quot;Je veux créer une application d&#39;assistance à la récupération post-partum pour aider les mamans à retrouver leur silhouette. Mais je m&#39;inquiète de la difficulté technique, en particulier pour la fonctionnalité de correction des mouvements par IA. Puis-je le faire seul ?&quot;</p><hr><h3 id="deuxieme-tour-l-ia-aide-a-planifier-le-mvp" tabindex="-1">Deuxième tour : L&#39;IA aide à planifier le MVP <a class="header-anchor" href="#deuxieme-tour-l-ia-aide-a-planifier-le-mvp" aria-label="Permalink to “Deuxième tour : L&#39;IA aide à planifier le MVP”">​</a></h3><p>L&#39;IA a répondu : &quot;Excellente question ! Faisons une planification de MVP (Produit Minimum Viable).&quot;</p><p>L&#39;IA a suggéré de procéder en trois phases. La première phase est de 1 à 2 mois, l&#39;objectif est de valider le besoin. Pas d&#39;application, d&#39;abord un mini-programme WeChat avec uniquement des cours post-partum (vidéo) et une communauté de suivi. Fournir un guidage des mouvements manuellement, les utilisateurs envoient des vidéos et les coachs répondent. L&#39;objectif est de vérifier si les mamans post-partum sont prêtes à payer.</p><p>La deuxième phase est de 3 à 6 mois : si la première phase est validée, ajouter les fonctionnalités clés. Développer la correction des mouvements par IA en utilisant des SDK existants, comme la reconnaissance corporelle de Baidu. Ajouter des plans personnalisés, optimiser la communauté.</p><p>La troisième phase est de 6 à 12 mois : passage à l&#39;échelle. Développer une application indépendante, collaborer avec des centres de rééducation post-partum, s&#39;étendre à la grossesse et à la préparation à la grossesse.</p><p>Concernant la réalisation technique, l&#39;IA a suggéré d&#39;utiliser des capacités IA existantes, comme les API de Baidu ou Tencent, sans développer à partir de zéro, pour réduire les coûts. Au début, utiliser un mode mixte humain + IA, avec une transition progressive.</p><p>Pour les coûts de démarrage, le développement du mini-programme coûte 10 000 à 20 000 yuans (en sous-traitance) ou vous pouvez le faire vous-même avec un AI IDE. Pour le contenu, collaborer avec des coachs de rééducation post-partum. Pour la promotion, commencer avec les groupes de mamans et Xiaohongshu.</p><p>L&#39;indicateur de validation est de 100 utilisateurs le premier mois, avec un taux de conversion payant de 10 %. Si cet objectif est atteint, le besoin est réel et l&#39;investissement continue ; sinon, ajuster la direction à temps.</p><hr><h3 id="troisieme-tour-xiaoming-exprime-ses-inquietudes" tabindex="-1">Troisième tour : Xiaoming exprime ses inquiétudes <a class="header-anchor" href="#troisieme-tour-xiaoming-exprime-ses-inquietudes" aria-label="Permalink to “Troisième tour : Xiaoming exprime ses inquiétudes”">​</a></h3><p>Xiaoming a réfléchi et demandé : &quot;Je m&#39;inquiète de la création de contenu. Les cours de rééducation post-partum nécessitent un guidage professionnel, je n&#39;ai pas de formation médicale, comment garantir la qualité des cours ?&quot;</p><hr><h3 id="quatrieme-tour-l-ia-propose-des-solutions" tabindex="-1">Quatrième tour : L&#39;IA propose des solutions <a class="header-anchor" href="#quatrieme-tour-l-ia-propose-des-solutions" aria-label="Permalink to “Quatrième tour : L&#39;IA propose des solutions”">​</a></h3><p>L&#39;IA a répondu : &quot;C&#39;est l&#39;inquiétude de beaucoup de créateurs de startups technologiques, mais il y a des solutions.&quot;</p><p>La première solution est de collaborer avec des professionnels. Trouver des coachs de rééducation post-partum, des médecins nutritionnistes hospitaliers. Vous fournissez la technologie et le produit, ils fournissent le contenu professionnel, avec un modèle de partage de revenus.</p><p>La deuxième solution est d&#39;intégrer du contenu existant de qualité. Au début, utiliser des vidéos de rééducation post-partum disponibles publiquement, sur YouTube ou Bilibili. Faire vous-même la vérification et l&#39;organisation du contenu, puis créer du contenu original plus tard.</p><p>La troisième solution est le contenu généré par les utilisateurs. Encourager les mamans expérimentées à partager leurs méthodes de récupération, utiliser le vote communautaire pour filtrer le contenu de qualité, et construire progressivement un écosystème de contenu.</p><p>L&#39;IA a recommandé de commencer par la première solution. La démarche concrète est de trouver 2 à 3 coachs de rééducation post-partum, négocier un partenariat : vous développez le produit, ils fournissent les cours. Partage des revenus : vous prenez 70 %, ils prennent 30 %. Cela garantit la qualité du contenu tout en réduisant les coûts. Coût de création des cours : 0 yuan (avec le modèle de partage). Vous n&#39;investissez que du temps de développement et des coûts de promotion.</p><hr><h3 id="cinquieme-tour-xiaoming-pose-la-question-de-la-promotion" tabindex="-1">Cinquième tour : Xiaoming pose la question de la promotion <a class="header-anchor" href="#cinquieme-tour-xiaoming-pose-la-question-de-la-promotion" aria-label="Permalink to “Cinquième tour : Xiaoming pose la question de la promotion”">​</a></h3><p>Xiaoming avait une dernière inquiétude : &quot;Les coûts de promotion seront-ils élevés ? Comment trouver le groupe des mamans post-partum ?&quot;</p><hr><h3 id="sixieme-tour-l-ia-propose-une-strategie-de-promotion" tabindex="-1">Sixième tour : L&#39;IA propose une stratégie de promotion <a class="header-anchor" href="#sixieme-tour-l-ia-propose-une-strategie-de-promotion" aria-label="Permalink to “Sixième tour : L&#39;IA propose une stratégie de promotion”">​</a></h3><p>L&#39;IA a répondu : &quot;Le groupe des mamans post-partum est en réalité facile à trouver, les coûts de promotion peuvent être très bas.&quot;</p><p>La meilleure approche est Xiaohongshu. Rechercher les mots-clés &quot;récupération post-partum&quot;, &quot;diastasis abdominal&quot;, trouver les blogueurs pertinents et les contacter en message privé. Proposer un &quot;essai gratuit d&#39;un mois&quot; en échange de promotion, le coût est quasiment nul.</p><p>Ensuite, les groupes de mamans. Rechercher des groupes WeChat et QQ, entrer sous couvert de &quot;partage d&#39;expérience de récupération post-partum&quot;, partager du contenu utile sans faire de publicité directe, construire progressivement la confiance.</p><p>Il est aussi possible de collaborer avec les maternités des hôpitaux, offrir des conseils gratuits de récupération post-partum, distribuer des flyers à l&#39;hôpital. Le coût est celui de l&#39;impression, quelques centaines de yuans. Ou collaborer avec des magasins pour bébés, placer du matériel promotionnel, offrir des cartes d&#39;essai avec l&#39;achat de produits pour bébé. Le coût est celui de la fabrication des cartes.</p><p>L&#39;indicateur de validation est : 100 utilisateurs le premier mois, 10 utilisateurs payants (taux de conversion de 10 %), coût total de promotion inférieur à 1 000 yuans, coût d&#39;acquisition inférieur à 10 yuans par personne. Si cet indicateur est atteint, le besoin est réel et l&#39;investissement peut continuer.</p><hr><h3 id="conclusion-xiaoming-a-un-plan-clair" tabindex="-1">Conclusion : Xiaoming a un plan clair <a class="header-anchor" href="#conclusion-xiaoming-a-un-plan-clair" aria-label="Permalink to “Conclusion : Xiaoming a un plan clair”">​</a></h3><p>Après 6 tours de conversation, Xiaoming avait enfin un plan clair.</p><p>La première phase est de 1 à 2 mois : créer un mini-programme WeChat, collaborer avec 2 à 3 coachs de rééducation post-partum (modèle de partage), fournir uniquement des cours post-partum (vidéo) et une communauté de suivi, avec un guidage des mouvements manuel. Objectif : 100 utilisateurs, taux de conversion payant de 10 %.</p><p>La deuxième phase est de 3 à 6 mois : si la première phase est validée, continuer à investir. Ajouter la correction des mouvements par IA, des plans personnalisés, optimiser la communauté.</p><p>La troisième phase est de 6 à 12 mois : développer une application indépendante, collaborer avec des centres de rééducation post-partum, s&#39;étendre à la grossesse et à la préparation.</p><p>Les coûts de démarrage sont très bas : développement avec un AI IDE (0 yuan), contenu partagé avec les coachs (0 yuan au début), promotion via Xiaohongshu et les groupes de mamans (moins de 1 000 yuans). Coût total : moins de 1 000 yuans.</p><hr><h3 id="la-methode-en-5-etapes-d-affinage-par-conversation-avec-l-ia" tabindex="-1">La méthode en 5 étapes d&#39;affinage par conversation avec l&#39;IA <a class="header-anchor" href="#la-methode-en-5-etapes-d-affinage-par-conversation-avec-l-ia" aria-label="Permalink to “La méthode en 5 étapes d&#39;affinage par conversation avec l&#39;IA”">​</a></h3><p>À travers ce cas, Xiaoming a tiré un processus standard de conversation avec l&#39;IA (détails en Annexe E).</p><p><strong>Première étape : Présenter l&#39;idée originale.</strong> Décrivez votre idée initiale, même si elle est grossière. Dites à l&#39;IA vos inquiétudes : concurrence féroce, difficulté de différenciation, etc.</p><p><strong>Deuxième étape : Demander à l&#39;IA de planifier le MVP.</strong> Quelles fonctionnalités le MVP doit-il inclure ? En combien de phases ? Quel est l&#39;objectif de chaque phase ? La réalisation technique est-elle difficile ?</p><p><strong>Troisième étape : Exprimer vos inquiétudes.</strong> Difficulté technique ? Coût de création de contenu ? Coût de promotion ? Difficulté d&#39;acquisition d&#39;utilisateurs ? Dites toutes vos réserves à l&#39;IA.</p><p><strong>Quatrième étape : Demander à l&#39;IA de proposer des solutions.</strong> L&#39;IA donnera des conseils concrets pour vos inquiétudes. Comparez plusieurs options, choisissez la meilleure. Estimation des coûts.</p><p><strong>Cinquième étape : Confirmer le plan final.</strong> Organisez un plan d&#39;action clair, fixez des indicateurs de validation. Si les objectifs ne sont pas atteints, ajustez la direction à temps.</p><p><strong>Modèle de prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un [concept de produit],</span></span>
<span class="line"><span>mais je m&#39;inquiète de [votre inquiétude].</span></span>
<span class="line"><span>Aidez-moi à :</span></span>
<span class="line"><span>1. Planifier un MVP</span></span>
<span class="line"><span>2. Donner des conseils techniques concrets</span></span>
<span class="line"><span>3. Estimer les coûts</span></span>
<span class="line"><span>4. Fixer des indicateurs de validation</span></span></code></pre></div><hr><h3 id="resume-de-cette-partie-ce-que-xiaoming-a-appris-1" tabindex="-1">Résumé de cette partie : Ce que Xiaoming a appris <a class="header-anchor" href="#resume-de-cette-partie-ce-que-xiaoming-a-appris-1" aria-label="Permalink to “Résumé de cette partie : Ce que Xiaoming a appris”">​</a></h3><p>Grâce à cette troisième partie, Xiaoming a compris trois choses.</p><p><strong>Premièrement, utiliser la conversation avec l&#39;IA pour affiner le concept de produit.</strong> N&#39;espérez pas obtenir une réponse parfaite en une seule conversation, itérez sur plusieurs tours. Dites à l&#39;IA vos observations, vos expériences, les retours de votre entourage. Si les suggestions de l&#39;IA ne sont pas pertinentes, signalez-le. En fin de compte, aboutissez à un plan d&#39;action concret.</p><p><strong>Deuxièmement, les principes fondamentaux du MVP.</strong> Minimal : ne faire que les fonctionnalités les plus essentielles. Validable : capable de vérifier rapidement si le besoin est réel. Peu coûteux : utiliser le coût le plus bas possible pour valider.</p><p><strong>Troisièmement, les indicateurs de validation.</strong> Taux de conversion payant supérieur à 10 % : le besoin est réel, cela vaut l&#39;investissement. Taux de conversion de 5 à 10 % : le besoin existe, mais doit être affiné. Taux de conversion inférieur à 5 % : le besoin n&#39;est pas valide, ajustez à temps.</p><hr><p>📦 <strong>Résultat du chapitre :</strong></p><ul><li>Un plan MVP clair</li><li>Un chemin de réalisation technique</li><li>Des indicateurs de validation définis</li></ul><hr><h2 id="epilogue-votre-action" tabindex="-1">Épilogue : Votre action <a class="header-anchor" href="#epilogue-votre-action" aria-label="Permalink to “Épilogue : Votre action”">​</a></h2><h3 id="methode-mnemotechnique" tabindex="-1">Méthode mnémotechnique <a class="header-anchor" href="#methode-mnemotechnique" aria-label="Permalink to “Méthode mnémotechnique”">​</a></h3><p><strong>Une personne, un sujet, un point d&#39;entrée ; segmenter horizontalement et creuser verticalement pour trouver les points de douleur ; affiner le concept par conversation avec l&#39;IA ; valider en 5 étapes avant d&#39;agir</strong></p><p><strong>Explication :</strong></p><ul><li><strong>Une personne :</strong> Partez de vous-même, vous comprenez naturellement ce groupe</li><li><strong>Un sujet :</strong> Concentrez-vous sur une chose spécifique, ne soyez pas gourmand</li><li><strong>Un point d&#39;entrée :</strong> Trouvez le point d&#39;entrée, plus c&#39;est spécifique, mieux c&#39;est</li><li><strong>Segmenter :</strong> Segmenter horizontalement les groupes, trouver les utilisateurs les plus disposés à payer</li><li><strong>Creuser :</strong> Creuser verticalement les scénarios, comprendre le parcours utilisateur complet</li><li><strong>Conversation IA :</strong> Utiliser la conversation avec l&#39;IA pour affiner le concept de produit</li><li><strong>Valider en 5 étapes :</strong> Utiliser la méthode en 5 étapes pour valider l&#39;authenticité du besoin</li></ul><hr><h3 id="exercice-post-chapitre" tabindex="-1">Exercice post-chapitre <a class="header-anchor" href="#exercice-post-chapitre" aria-label="Permalink to “Exercice post-chapitre”">​</a></h3><p>Choisissez un petit problème de votre vie quotidienne et développez-le avec la méthode de ce chapitre :</p><div class="tip custom-block"><p class="custom-block-title">Mission d&#39;exercice</p><p><strong>1. Décrire le problème</strong> (1 phrase)</p><ul><li>Exemple : &quot;Je veux créer une application de gestion de dépenses pour aider les utilisateurs à suivre leurs dépenses&quot;</li></ul><p><strong>2. Segmenter : Trouver 3 groupes avec des besoins potentiellement différents</strong></p><ul><li>Exemple : petits entrepreneurs, parents d&#39;étudiants à l&#39;étranger, freelances</li></ul><p><strong>3. Choisir un groupe, creuser verticalement : Décrire leur scénario complet et leurs émotions réelles</strong></p><ul><li>Exemple : le scénario des parents d&#39;étudiants à l&#39;étranger -- vouloir savoir combien leur enfant dépense, mais l&#39;enfant ne le dit pas</li></ul><p><strong>4. Reconstruire le concept de produit : D&#39;&quot;une fonctionnalité&quot; à &quot;une solution&quot;</strong></p><ul><li>Exemple : &quot;Gestionnaire de budget d&#39;études&quot; -- pas seulement enregistrer les dépenses, mais permettre aux parents d&#39;avoir une vue claire des dépenses de leur enfant à l&#39;étranger</li></ul><p><strong>5. Évaluer votre idée avec la liste de validation</strong> (voir Annexe F)</p><p><strong>Partagez votre analyse dans la communauté et discutez avec les autres apprenants !</strong></p></div><hr><h2 id="annexe-methodologie-sop" tabindex="-1">Annexe : Méthodologie SOP <a class="header-anchor" href="#annexe-methodologie-sop" aria-label="Permalink to “Annexe : Méthodologie SOP”">​</a></h2><h3 id="annexe-a-la-methode-en-5-etapes-pour-analyser-les-besoins" tabindex="-1">Annexe A : La méthode en 5 étapes pour analyser les besoins <a class="header-anchor" href="#annexe-a-la-methode-en-5-etapes-pour-analyser-les-besoins" aria-label="Permalink to “Annexe A : La méthode en 5 étapes pour analyser les besoins”">​</a></h3><p>Quand vous avez une idée, comment déterminer rapidement si elle vaut la peine d&#39;investir ?</p><p><strong>Première étape : Validation utilisateur -- Trouver 10 utilisateurs cibles</strong></p><p><strong>Ne demandez pas :</strong> &quot;Utiliseriez-vous mon produit ?&quot; (taux de faux positifs de 90 %)</p><p><strong>Demandez :</strong></p><ol><li>&quot;Comment résolvez-vous ce problème actuellement ?&quot; (comprendre le comportement réel)</li><li>&quot;Au cours de la semaine dernière, combien de fois ce problème vous a-t-il gêné ?&quot; (comprendre la fréquence)</li><li>&quot;Combien d&#39;argent / de temps avez-vous dépensé pour le résoudre ?&quot; (comprendre la volonté de payer)</li><li>&quot;S&#39;il existait une solution, mais qu&#39;elle nécessitait de changer vos habitudes, seriez-vous prêt ?&quot; (comprendre le coût du changement)</li></ol><p><strong>Critères de jugement :</strong></p><ul><li>Si 3 utilisateurs ou plus disent &quot;je galère avec ça tous les jours&quot; -- c&#39;est peut-être un point de douleur</li><li>Si l&#39;utilisateur dit &quot;c&#39;est intéressant, mais je ne suis pas pressé&quot; -- c&#39;est probablement un point de démangeaison</li><li>Si l&#39;utilisateur dit &quot;j&#39;utilise actuellement XX pour résoudre ça, mais je n&#39;en suis pas satisfait&quot; -- il y a une opportunité</li></ul><p><strong>Question clé :</strong> Quelle méthode l&#39;utilisateur utilise-t-il actuellement pour résoudre ce problème ?</p><table tabindex="0"><thead><tr><th>Type de solution alternative</th><th>Description</th><th>Jugement d&#39;opportunité</th></tr></thead><tbody><tr><td><strong>Pas de solution alternative</strong></td><td>L&#39;utilisateur tolère le problème</td><td>Grande opportunité, mais nécessite d&#39;éduquer le marché</td></tr><tr><td><strong>Méthode rudimentaire</strong></td><td>Excel, manuel, collaboration entre plusieurs personnes</td><td>Bonne opportunité, les utilisateurs veulent une meilleure solution</td></tr><tr><td><strong>Combinaison de plusieurs outils</strong></td><td>Outil A + Outil B + Outil C</td><td>Bonne opportunité, l&#39;intégration a de la valeur</td></tr><tr><td><strong>Produit mature</strong></td><td>Mais l&#39;utilisateur n&#39;est pas satisfait</td><td>Opportunité, mais nécessite une différenciation</td></tr><tr><td><strong>Produit mature</strong></td><td>L&#39;utilisateur est satisfait</td><td>Opportunité faible, sauf innovation disruptive</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Qu&#39;est-ce qu&#39;une &quot;innovation disruptive&quot; ?</p><p><strong>Définition simple :</strong> Ne pas faire un meilleur produit, mais servir un groupe d&#39;utilisateurs auparavant ignoré de manière plus simple / moins chère.</p><p><strong>Exemples :</strong></p><ul><li>Téléphone classique → smartphone (pas plus de fonctionnalités, mais une interaction totalement différente)</li><li>Taxi classique → Uber (pas de meilleures voitures, mais rendre la course disponible partout à tout moment)</li><li>Librairie classique → livre numérique (pas plus de livres, mais faciliter le transport et l&#39;achat)</li></ul><p><strong>Clé :</strong> L&#39;innovation disruptive commence souvent par le &quot;bas du marché&quot; ou un &quot;nouveau segment d&#39;utilisateurs&quot;, puis grignote progressivement vers le haut.</p></div><p><strong>Cas :</strong></p><ul><li>Les diabétiques utilisent actuellement &quot;l&#39;expérience + l&#39;intuition&quot; pour contrôler leur alimentation (méthode rudimentaire) -- grande opportunité</li><li>Les personnes au régime utilisent Boohee (produit mature, satisfaction moyenne) -- opportunité de segmentation</li><li>Les étudiants utilisent des groupes WeChat pour les transactions de seconde main (combinaison d&#39;outils) -- opportunité d&#39;intégration</li></ul><p><strong>La méthode la plus efficace : la prévente ou l&#39;acompte</strong></p><p><strong>Étapes :</strong></p><ol><li>Créez une landing page simple décrivant votre concept de produit</li><li>Ajoutez un bouton &quot;Prévente&quot; ou &quot;Réservation&quot;</li><li>Regardez combien de personnes sont prêtes à payer (même 1 yuan)</li></ol><p><strong>Critères de jugement :</strong></p><ul><li>Utilisateurs prêts à payer un acompte &gt; 10 % : besoin réel, ça vaut le coup</li><li>Utilisateurs prêts à payer un acompte 5-10 % : le besoin existe, mais doit être affiné</li><li>Utilisateurs prêts à payer un acompte &lt; 5 % : le besoin n&#39;est pas valide, ou le concept a un problème</li></ul><p><strong>Attention :</strong> Beaucoup de gens disent &quot;je l&#39;achèterai&quot;, mais seuls ceux qui paient vraiment sont vos utilisateurs cibles.</p><p><strong>Formule simple :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Taille du marché potentiel = Nombre d&#39;utilisateurs cibles × Volonté de payer × Prix moyen</span></span></code></pre></div><p><strong>Cas : Plateforme de transactions de seconde main universitaire</strong></p><ul><li>Utilisateurs cibles : 40 millions d&#39;étudiants en Chine</li><li>Ayant besoin de transactions de seconde main : 50 % = 20 millions</li><li>Prêts à utiliser la plateforme : 10 % = 2 millions</li><li>Fréquence de transaction annuelle : 2</li><li>Commission de la plateforme : 5 %</li><li>Prix moyen : 100 yuans</li><li>Taille du marché potentiel = 2 millions × 2 × 100 × 5 % = 20 millions de yuans/an</li></ul><p><strong>Critères de jugement :</strong></p><ul><li>Taille du marché &gt; 1 milliard : grand segment, ça vaut le coup</li><li>Taille du marché 100 millions - 1 milliard : segment moyen, faisable mais plafond évident</li><li>Taille du marché &lt; 100 millions : marché de niche, adapté pour une activité secondaire</li></ul><p><strong>Question clé :</strong> Si le produit fonctionne, que faire contre la copie ?</p><p><strong>Types de barrières concurrentielles courantes :</strong></p><table tabindex="0"><thead><tr><th>Type de barrière</th><th>Description</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Effet de réseau</strong></td><td>Plus il y a d&#39;utilisateurs, plus le produit a de la valeur</td><td>WeChat, Uber</td></tr><tr><td><strong>Accumulation de données</strong></td><td>Plus de données, algorithmes plus précis</td><td>Jinri Toutiao, TikTok</td></tr><tr><td><strong>Notoriété de marque</strong></td><td>Occupation de l&#39;esprit utilisateur</td><td>Coca-Cola, Nike</td></tr><tr><td><strong>Économies d&#39;échelle</strong></td><td>Plus la taille augmente, plus les coûts baissent</td><td>JD Logistics, Amazon</td></tr><tr><td><strong>Brevets technologiques</strong></td><td>Barrière technologique fondamentale</td><td>Huawei, DJI</td></tr><tr><td><strong>Coûts de migration</strong></td><td>Les coûts de changement pour l&#39;utilisateur sont élevés</td><td>Logiciel d&#39;entreprise, systèmes d&#39;exploitation</td></tr></tbody></table><p><strong>La réalité des projets en début de phase :</strong></p><ul><li>La plupart des projets en début de phase n&#39;ont pas de barrières évidentes</li><li>Mais ce n&#39;est pas grave, la clé est de <strong>aller vite</strong></li><li>D&#39;abord conquérir le marché, puis construire des barrières</li></ul><hr><h3 id="annexe-b-methode-de-segmentation-horizontale" tabindex="-1">Annexe B : Méthode de segmentation horizontale <a class="header-anchor" href="#annexe-b-methode-de-segmentation-horizontale" aria-label="Permalink to “Annexe B : Méthode de segmentation horizontale”">​</a></h3><p>N&#39;essayez pas de servir &quot;tous les utilisateurs XX&quot;, mais trouvez <strong>un groupe spécifique</strong> dont les besoins sont plus intenses et plus concrets.</p><p><strong>Première étape : Lister tous les segments possibles</strong></p><p>Pour votre concept de produit, listez tous les groupes possibles.</p><p><strong>Deuxième étape : Évaluer la valeur commerciale de chaque groupe</strong></p><table tabindex="0"><thead><tr><th>Dimension d&#39;évaluation</th><th>Description</th></tr></thead><tbody><tr><td>Intensité du point de douleur</td><td>Le besoin de ce groupe est-il un point de douleur ou un point de démangeaison ?</td></tr><tr><td>Volonté de payer</td><td>Combien seraient-ils prêts à payer pour une solution ?</td></tr><tr><td>Taille du marché</td><td>Combien de personnes dans ce groupe ?</td></tr><tr><td>Niveau de concurrence</td><td>Les solutions existantes sont-elles satisfaisantes ?</td></tr><tr><td>Votre compréhension du groupe</td><td>Comprenez-vous ce groupe ? Avez-vous des canaux d&#39;accès ?</td></tr></tbody></table><p><strong>Troisième étape : Choisir un groupe pour une analyse approfondie</strong></p><p>Choisissez un groupe qui a :</p><ul><li>Le point de douleur le plus intense</li><li>La plus forte volonté de payer</li><li>Que vous comprenez le mieux</li><li>Une concurrence relativement faible</li></ul><div class="tip custom-block"><p class="custom-block-title">Exemple de segmentation</p><p><strong>Concept de produit :</strong> Application de gestion de dépenses</p><table tabindex="0"><thead><tr><th>Segment</th><th>Point de douleur</th><th>Volonté de payer</th><th>Taille du marché</th><th>Concurrence</th></tr></thead><tbody><tr><td>Employés de bureau</td><td>Saisie fastidieuse</td><td>Faible</td><td>Grande</td><td>Élevée</td></tr><tr><td>Petits entrepreneurs</td><td>Confusion dépenses personnelles/professionnelles</td><td>Élevée</td><td>Moyenne</td><td>Moyenne</td></tr><tr><td>Freelances</td><td>Revenus instables, besoin de prévoir les flux de trésorerie</td><td>Élevée</td><td>Moyenne</td><td>Moyenne</td></tr><tr><td>Parents d&#39;étudiants à l&#39;étranger</td><td>Veulent savoir combien leur enfant dépense, mais l&#39;enfant ne le dit pas</td><td>Élevée</td><td>Petite</td><td>Faible</td></tr></tbody></table><p><strong>Choix :</strong> Parents d&#39;étudiants à l&#39;étranger (point de douleur le plus intense, forte volonté de payer, concurrence relativement faible)</p></div><hr><h3 id="annexe-c-methode-d-approfondissement-vertical-des-scenarios" tabindex="-1">Annexe C : Méthode d&#39;approfondissement vertical des scénarios <a class="header-anchor" href="#annexe-c-methode-d-approfondissement-vertical-des-scenarios" aria-label="Permalink to “Annexe C : Méthode d&#39;approfondissement vertical des scénarios”">​</a></h3><p>Après avoir identifié le groupe, ne vous arrêtez pas à une fonctionnalité unique, mais comprenez le <strong>scénario utilisateur complet</strong>.</p><p><strong>Première étape : Décrire une journée type de l&#39;utilisateur</strong></p><p>Du matin au soir, décrivez le scénario complet d&#39;utilisation de votre produit.</p><p><strong>Deuxième étape : Analyser les points de douleur de chaque scénario</strong></p><p>Dans chaque scénario, quels problèmes l&#39;utilisateur rencontre-t-il ? Quelles émotions ?</p><p><strong>Troisième étape : Trouver les déclencheurs émotionnels</strong></p><p>Peur, anxiété, impuissance, solitude, colère, regret...</p><p><strong>Quatrième étape : Reconstruire la valeur</strong></p><p>Sur la base des scénarios et des émotions, reconstruisez la valeur du produit.</p><div class="tip custom-block"><p class="custom-block-title">Exemple d&#39;approfondissement</p><p><strong>Groupe :</strong> Mamans post-partum</p><table tabindex="0"><thead><tr><th>Heure</th><th>Scénario</th><th>Point de douleur</th><th>Émotion</th></tr></thead><tbody><tr><td>6h du matin</td><td>Le bébé vient de s&#39;endormir, 30 minutes de libre</td><td>Ne sait pas quels mouvements sont sûrs</td><td>Peur</td></tr><tr><td>10h du matin</td><td>Berce le bébé, le dos fait mal</td><td>Les mains sont occupées, veut faire de la rééducation</td><td>Anxiété</td></tr><tr><td>15h</td><td>Le bébé dort, veut faire du sport</td><td>Très fatiguée, ne sait pas si elle peut encore s&#39;entraîner</td><td>Impuissance</td></tr><tr><td>20h</td><td>Enfin du temps libre</td><td>Se regarde dans le miroir, se sent détruite</td><td>Dépression</td></tr><tr><td>Long terme</td><td>Personne ne comprend</td><td>Se sent seule dans sa souffrance</td><td>Solitude</td></tr></tbody></table><p><strong>Valeur reconstruite :</strong> Passer d&#39;&quot;outil de fitness&quot; à &quot;coach de rééducation + soutien psychologique&quot;</p></div><hr><h3 id="annexe-d-plus-d-exemples-d-idees-ordinaires-transformees-en-bonnes-idees" tabindex="-1">Annexe D : Plus d&#39;exemples d&#39;idées ordinaires transformées en bonnes idées <a class="header-anchor" href="#annexe-d-plus-d-exemples-d-idees-ordinaires-transformees-en-bonnes-idees" aria-label="Permalink to “Annexe D : Plus d&#39;exemples d&#39;idées ordinaires transformées en bonnes idées”">​</a></h3><h4 id="exemple-1-de-application-de-depenses-a-gestionnaire-de-budget-d-etudes" tabindex="-1">Exemple 1 : De &quot;application de dépenses&quot; à &quot;Gestionnaire de budget d&#39;études&quot; <a class="header-anchor" href="#exemple-1-de-application-de-depenses-a-gestionnaire-de-budget-d-etudes" aria-label="Permalink to “Exemple 1 : De &quot;application de dépenses&quot; à &quot;Gestionnaire de budget d&#39;études&quot;”">​</a></h4><p><strong>Idée ordinaire :</strong> Application de comptabilité automatique, connectée à la carte bancaire pour classer automatiquement les dépenses</p><p><strong>Problème :</strong> Il existe déjà Sui Shou Ji, Wacai, les relevés Alipay...</p><p><strong>Segmentation :</strong></p><ul><li>Parents d&#39;étudiants à l&#39;étranger : veulent savoir combien leur enfant dépense à l&#39;étranger et s&#39;il dépasse le budget</li></ul><p><strong>Approfondissement vertical :</strong></p><ul><li>Le point de douleur n&#39;est pas &quot;enregistrer les dépenses&quot;, mais <strong>&quot;le sentiment de perte de contrôle&quot;</strong> -- ne pas savoir combien l&#39;enfant dépense ni où</li><li>Scénario : chaque mois, voir le relevé de carte de crédit, mais l&#39;enfant ne dit jamais spontanément ce qu&#39;il a acheté</li></ul><p><strong>Reconstruit :</strong> &quot;Gestionnaire de budget d&#39;études&quot; -- pas seulement enregistrer, mais permettre aux parents d&#39;avoir une vue claire des dépenses de leur enfant à l&#39;étranger</p><p><strong>Fonctionnalités clés :</strong></p><ul><li>Synchronisation en temps réel des dépenses de l&#39;enfant</li><li>Alerte de dépassement de budget</li><li>Rapport mensuel d&#39;analyse des dépenses</li><li>Comparaison avec les autres étudiants du même profil</li></ul><hr><h4 id="exemple-2-de-outil-pomodoro-a-preuve-de-travail-a-distance" tabindex="-1">Exemple 2 : De &quot;outil Pomodoro&quot; à &quot;Preuve de travail à distance&quot; <a class="header-anchor" href="#exemple-2-de-outil-pomodoro-a-preuve-de-travail-a-distance" aria-label="Permalink to “Exemple 2 : De &quot;outil Pomodoro&quot; à &quot;Preuve de travail à distance&quot;”">​</a></h4><p><strong>Idée ordinaire :</strong> Application Pomodoro pour aider les utilisateurs à se concentrer</p><p><strong>Problème :</strong> Le temps d&#39;écran du téléphone, Forest, Pomodoro ToDo...</p><p><strong>Segmentation :</strong></p><ul><li>Travailleurs à distance : besoin de prouver à leur patron &quot;je travaille vraiment&quot;</li></ul><p><strong>Approfondissement vertical :</strong></p><ul><li>Le point de douleur n&#39;est pas &quot;le manque de concentration&quot;, mais <strong>&quot;la crise de confiance&quot;</strong> -- le patron ne me voit pas, comment prouver que je travaille ?</li><li>Scénario : chaque soir, le patron demande &quot;comment s&#39;est passé le travail aujourd&#39;hui ?&quot;, impossible de prouver</li></ul><p><strong>Reconstruit :</strong> &quot;Preuve de travail à distance&quot; -- aider les travailleurs à distance à établir la confiance avec leur employeur</p><p><strong>Fonctionnalités clés :</strong></p><ul><li>Suivi automatique du temps de travail</li><li>Rapports de productivité</li><li>Résumé d&#39;activité à l&#39;écran (version respectueuse de la vie privée)</li><li>Génération automatique quotidienne d&#39;un &quot;rapport de travail&quot; envoyé au supérieur</li></ul><hr><h4 id="exemple-3-de-echange-de-livres-d-occasion-a-bibliotheque-de-livres-d-images" tabindex="-1">Exemple 3 : De &quot;échange de livres d&#39;occasion&quot; à &quot;Bibliothèque de livres d&#39;images&quot; <a class="header-anchor" href="#exemple-3-de-echange-de-livres-d-occasion-a-bibliotheque-de-livres-d-images" aria-label="Permalink to “Exemple 3 : De &quot;échange de livres d&#39;occasion&quot; à &quot;Bibliothèque de livres d&#39;images&quot;”">​</a></h4><p><strong>Idée ordinaire :</strong> Plateforme d&#39;échange de livres d&#39;occasion</p><p><strong>Problème :</strong> Duozhuayu, Xianyu, Kongfuzi...</p><p><strong>Segmentation :</strong></p><ul><li>Mamans : les livres d&#39;images de leurs enfants ne servent plus une fois lus, mais les neufs sont chers</li></ul><p><strong>Approfondissement vertical :</strong></p><ul><li>Le point de douleur n&#39;est pas &quot;les livres sont chers&quot;, mais <strong>&quot;la durée de vie courte des livres d&#39;images&quot;</strong> -- le livre qu&#39;un enfant lit à 3 ans ne l&#39;intéresse plus à 4 ans</li><li>Scénario : la maison est pleine de livres d&#39;images que personne ne lit plus, mais c&#39;est dommage de les jeter</li></ul><p><strong>Reconstruit :</strong> &quot;Bibliothèque de livres d&#39;images à domicile&quot; -- pas vendre des livres d&#39;occasion, mais offrir un &quot;service de location&quot; de livres d&#39;images</p><p><strong>Fonctionnalités clés :</strong></p><ul><li>Abonnement de livres d&#39;images (5 livres adaptés à l&#39;âge livrés chaque mois, renvoyez-les pour en recevoir de nouveaux)</li><li>Suivi de la progression de lecture</li><li>Recommandations adaptées à l&#39;âge</li><li>Garantie de désinfection</li></ul><hr><h3 id="annexe-e-la-methode-en-5-etapes-d-affinage-par-conversation-avec-l-ia" tabindex="-1">Annexe E : La méthode en 5 étapes d&#39;affinage par conversation avec l&#39;IA <a class="header-anchor" href="#annexe-e-la-methode-en-5-etapes-d-affinage-par-conversation-avec-l-ia" aria-label="Permalink to “Annexe E : La méthode en 5 étapes d&#39;affinage par conversation avec l&#39;IA”">​</a></h3><p>À travers plusieurs tours de conversation avec l&#39;IA, transformez progressivement une idée ordinaire en un concept de produit précis et réalisable.</p><p><strong>Action :</strong></p><ul><li>Décrivez votre idée initiale (même grossière)</li><li>Dites à l&#39;IA vos inquiétudes (concurrence féroce, difficulté de différenciation, etc.)</li></ul><p><strong>Prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un [concept de produit],</span></span>
<span class="line"><span>mais je remarque que [problème/inquiétude].</span></span></code></pre></div><p><strong>Action :</strong></p><ul><li>Demandez à l&#39;IA de planifier un MVP</li><li>Discutez de la difficulté technique et des coûts</li><li>Fixez des indicateurs de validation</li></ul><p><strong>Prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Aidez-moi à :</span></span>
<span class="line"><span>1. Planifier un MVP</span></span>
<span class="line"><span>2. Donner des conseils techniques concrets</span></span>
<span class="line"><span>3. Estimer les coûts</span></span>
<span class="line"><span>4. Fixer des indicateurs de validation</span></span></code></pre></div><p><strong>Action :</strong></p><ul><li>Difficulté technique ?</li><li>Coût de création de contenu ?</li><li>Coût de promotion ?</li><li>Difficulté d&#39;acquisition d&#39;utilisateurs ?</li></ul><p><strong>Prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je m&#39;inquiète de :</span></span>
<span class="line"><span>1. [Inquiétude 1]</span></span>
<span class="line"><span>2. [Inquiétude 2]</span></span>
<span class="line"><span>3. [Inquiétude 3]</span></span></code></pre></div><p><strong>Action :</strong></p><ul><li>Pour chacune de vos inquiétudes, obtenir des conseils concrets</li><li>Comparer plusieurs options, choisir la meilleure</li><li>Estimation des coûts</li></ul><p><strong>Prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pour mes inquiétudes, veuillez proposer des solutions concrètes.</span></span></code></pre></div><p><strong>Action :</strong></p><ul><li>Organiser un plan d&#39;action clair</li><li>Fixer des indicateurs de validation</li><li>Si les objectifs ne sont pas atteints, ajuster la direction</li></ul><p><strong>Prompt :</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Veuillez m&#39;aider à organiser un plan d&#39;action clair.</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Conseils clés</p><ul><li><strong>Plusieurs tours :</strong> N&#39;espérez pas une réponse parfaite en une seule conversation, itérez</li><li><strong>Fournir des informations :</strong> Dites à l&#39;IA vos observations, expériences et retours</li><li><strong>Questionner l&#39;IA :</strong> Si les suggestions de l&#39;IA ne sont pas pertinentes, signalez-le</li><li><strong>Se concentrer sur l&#39;exécution :</strong> Aboutissez toujours à un plan d&#39;action concret</li></ul></div><hr><h3 id="annexe-f-liste-de-validation-des-besoins" tabindex="-1">Annexe F : Liste de validation des besoins <a class="header-anchor" href="#annexe-f-liste-de-validation-des-besoins" aria-label="Permalink to “Annexe F : Liste de validation des besoins”">​</a></h3><p>Avant de décider d&#39;investir du temps dans le développement, utilisez la liste suivante pour valider votre idée -- <strong>la question clé est : les utilisateurs paieront-ils pour cela ?</strong></p><div class="tip custom-block"><p class="custom-block-title">Liste de validation des besoins</p><p><strong>1. Clarté du profil utilisateur</strong></p><ul><li>☐ Pouvez-vous décrire l&#39;utilisateur cible en une phrase ?</li><li>☐ Pouvez-vous dire quelle est sa solution alternative actuelle ?</li><li>☐ Pouvez-vous décrire les détails concrets de son scénario d&#39;utilisation ?</li><li>☐ Ce groupe a-t-il la capacité de payer ?</li></ul><p><strong>2. Évaluation de l&#39;intensité du point de douleur</strong></p><ul><li>☐ Combien l&#39;utilisateur paie-t-il actuellement pour résoudre ce problème ? (temps/argent/énergie)</li><li>☐ Si le problème n&#39;est pas résolu, quelles sont les conséquences ?</li><li>☐ L&#39;utilisateur cherche-t-il déjà des solutions ?</li><li>☐ Combien l&#39;utilisateur est-il prêt à payer pour résoudre ce problème ?</li></ul><p><strong>3. Différenciation de la solution</strong></p><ul><li>☐ Par rapport aux solutions existantes, quel est votre avantage ?</li><li>☐ Cet avantage est-il suffisant pour que les utilisateurs changent ?</li><li>☐ Est-il difficile pour les grandes plateformes de copier vos fonctionnalités ?</li><li>☐ Votre différenciation suffit-elle à justifier le paiement des utilisateurs ?</li></ul><p><strong>4. Faisabilité du modèle économique</strong></p><ul><li>☐ Les utilisateurs paieront-ils ? Combien ? (il faut tester réellement)</li><li>☐ Quel est le coût d&#39;acquisition approximatif ?</li><li>☐ La valeur vie du client (LTV) peut-elle couvrir le coût d&#39;acquisition (CAC) ?</li><li>☐ Y a-t-il d&#39;autres modes de monétisation ? (publicité, services premium, B2B, etc.)</li></ul><p><strong>5. Plan de validation rapide</strong></p><ul><li>☐ Pouvez-vous créer un prototype testable avec un coût minimal (1-2 semaines) ?</li><li>☐ Pouvez-vous trouver 10 utilisateurs cibles pour des entretiens ?</li><li>☐ Pouvez-vous concevoir une expérience pour valider l&#39;hypothèse clé ?</li><li>☐ Pouvez-vous demander un acompte pour valider la volonté de payer ?</li></ul></div><p><strong>Ne demandez pas &quot;Utiliseriez-vous ce produit ?&quot;</strong> Ce type de question n&#39;obtient que des réponses faussement positives.</p><p><strong>Demandez :</strong></p><ul><li>&quot;Comment résolvez-vous ce problème actuellement ?&quot; (comprendre le comportement réel)</li><li>&quot;Au cours de la semaine dernière, combien de fois ce problème vous a-t-il gêné ?&quot; (comprendre la fréquence)</li><li>&quot;S&#39;il existait une solution, mais qu&#39;elle nécessitait de changer vos habitudes, seriez-vous prêt ?&quot; (comprendre le coût du changement)</li><li>&quot;Si cela coûtait XX yuans, l&#39;achèteriez-vous ?&quot; (comprendre la volonté de payer)</li></ul><p><strong>La meilleure validation :</strong> Demander un acompte. Beaucoup de gens disent qu&#39;ils paieront, mais seuls ceux qui paient vraiment sont vos utilisateurs cibles.</p><p><strong>Indicateurs clés :</strong></p><ul><li>Pourcentage d&#39;utilisateurs prêts à payer un acompte &gt; 10 % : besoin réel, vaut l&#39;investissement</li><li>Pourcentage d&#39;utilisateurs prêts à payer un acompte 5-10 % : le besoin existe, mais doit être affiné</li><li>Pourcentage d&#39;utilisateurs prêts à payer un acompte &lt; 5 % : le besoin n&#39;est pas valide, ou le concept a un problème</li></ul><hr><h2 id="resume-du-chapitre" tabindex="-1">Résumé du chapitre <a class="header-anchor" href="#resume-du-chapitre" aria-label="Permalink to “Résumé du chapitre”">​</a></h2><p>Dans ce chapitre, à travers l&#39;histoire de Xiaoming, nous avons appris à examiner les idées produit avec le regard d&#39;un chef de produit -- <strong>le centre de tout est toujours : les utilisateurs paieront-ils pour cela ?</strong></p><div class="info custom-block"><p class="custom-block-title">Points clés</p><p><strong>1. Les trois critères d&#39;un vrai besoin :</strong></p><ul><li>Les utilisateurs sont prêts à payer (critère le plus important)</li><li>Les utilisateurs sont prêts à changer de comportement</li><li>Sans solution, les utilisateurs subissent une perte importante</li></ul><p><strong>2. Le chemin d&#39;une idée ordinaire à un produit payant :</strong></p><ul><li><strong>Segmentation horizontale :</strong> Trouver un groupe spécifique, plus le segment est étroit, plus la volonté de payer est forte</li><li><strong>Approfondissement vertical :</strong> Comprendre le scénario complet, résoudre les émotions et pas seulement les fonctionnalités</li><li><strong>Reconstruction de la valeur :</strong> Passer d&#39;un outil à une solution, établir une raison de payer</li></ul><p><strong>3. Éviter les pièges des faux besoins :</strong></p><ul><li>Résoudre de faux points de douleur (points de démangeaison au lieu de points de douleur)</li><li>Marché trop petit pour soutenir un modèle économique</li><li>Solution plus complexe que le problème</li></ul><p><strong>4. Méthodes de validation de la volonté de payer :</strong></p><ul><li>Trouver 10 utilisateurs cibles pour des entretiens approfondis</li><li>Demander un acompte pour valider la véritable intention</li><li>Le pourcentage d&#39;utilisateurs prêts à payer un acompte &gt; 10 % justifie l&#39;investissement</li></ul><p><strong>5. Affiner le concept de produit par conversation avec l&#39;IA :</strong></p><ul><li>Itérer sur plusieurs tours, optimiser continuellement</li><li>Se concentrer sur l&#39;exécution, aboutir à un plan d&#39;action</li><li>Fixer des indicateurs de validation, ajuster à temps</li></ul></div><p><strong>À retenir :</strong> Un bon chef de produit ne crée pas des besoins à partir de rien, il découvre les vrais besoins <strong>ignorés, sous-estimés ou mal satisfaits</strong>, et trouve un moyen de faire en sorte que les utilisateurs soient prêts à payer pour cela.</p><p>Dans le prochain chapitre, nous prendrons une idée validée et apprendrons à utiliser un AI IDE pour la transformer en un prototype de produit interactif.</p>`,331))])}}});export{f as __pageData,q as default};
